code.ts:
interface FlyBehaviour {
  fly(): string
}
class Wings implements FlyBehaviour {
  fly() { return 'flaps its wings' }
}
class CannotFly implements FlyBehaviour {
  fly() { return "can't fly" }
}

class Duck {
  constructor(public name: string, private flyer: FlyBehaviour) {}
  fly() { return `${this.name} ${this.flyer.fly()}` } // delegate
  setFlyer(f: FlyBehaviour) { this.flyer = f }         // swap at run time
}

code.py:
class Wings:
    def fly(self): return "flaps its wings"

class CannotFly:
    def fly(self): return "can't fly"

class Duck:
    def __init__(self, name, flyer):
        self.name = name
        self._flyer = flyer

    def fly(self):                      # delegate
        return f"{self.name} {self._flyer.fly()}"

    def set_flyer(self, flyer):         # swap at run time
        self._flyer = flyer

sections.body:
Inheritance isn't banned. It fits when:

- the relationship is a **true, stable is-a**, and the subclass can honour every promise the parent makes (Liskov);
- you are extending a framework that is **designed** for it, such as an Android `Activity` or `ViewModel`, or an abstract base class meant for subclassing;
- the hierarchy is **shallow**, one or two levels.

In interviews, "favour composition" doesn't mean "never inherit". Say you would default to composition for sharing behaviour, and use inheritance for genuine is-a types.

